:root {
  /* Define base font sizes and ranges */
  --min-body-font: 1rem;     /* 16px minimum */
  --max-body-font: 1.25rem;  /* 20px maximum */
  --viewport-scalar: 1.5vw;  /* Scales with viewport width (e.g., 1.5% of viewport width) */
}

body {
  /* Fluid font size with a min of 1rem and a max of 1.25rem */
  font-size: clamp(var(--min-body-font), var(--viewport-scalar) + 0.5rem, var(--max-body-font));
  font-family: 'Inter', sans-serif; /* Example web font */
  line-height: 1.6;
}

h1 {
  /* Example for a larger heading: min 2.5rem, fluid 5vw + 1rem, max 4rem */
  font-size: clamp(2.5rem, 5vw + 1rem, 4rem);
  font-weight: 700;
  margin-bottom: 0.5em;
}
